create table if not exists public.market_quotes (symbol text primary key,bid numeric not null,ask numeric not null,mid numeric not null,spread numeric not null,provider_timestamp timestamptz,received_at timestamptz not null default now(),updated_at timestamptz not null default now(),source text,connection_status text,latency_ms integer);
create table if not exists public.market_quote_ticks (id bigint generated always as identity primary key,symbol text not null,bid numeric not null,ask numeric not null,mid numeric not null,spread numeric not null,provider_timestamp timestamptz,received_at timestamptz not null default now(),source text);
create index if not exists market_quote_ticks_symbol_received_idx on public.market_quote_ticks(symbol,received_at desc);
create table if not exists public.aiva_historical_m1 (id bigint generated always as identity primary key,symbol text not null,timeframe text not null check(timeframe in ('M1','M5')),candle_at timestamptz not null,bid_open numeric not null,bid_high numeric not null,bid_low numeric not null,bid_close numeric not null,ask_open numeric not null,ask_high numeric not null,ask_low numeric not null,ask_close numeric not null,spread_open numeric,spread_high numeric,spread_low numeric,spread_close numeric,bid_volume numeric,ask_volume numeric,source text,unique(symbol,timeframe,candle_at));
create index if not exists aiva_historical_m1_symbol_tf_time_idx on public.aiva_historical_m1(symbol,timeframe,candle_at desc);
create table if not exists public.aiva_historical_daily (id bigint generated always as identity primary key,symbol text not null,session_date date not null,close numeric not null,source text,fetched_at timestamptz,unique(symbol,session_date));
create table if not exists public.market_analysis_runs (id uuid primary key default gen_random_uuid(),symbol text not null,decision text not null,simulations integer,confidence numeric,probability_up numeric,probability_down numeric,expected_move numeric,risk_score numeric,rationale text,features jsonb not null default '{}'::jsonb,scenarios jsonb not null default '[]'::jsonb,created_at timestamptz not null default now(),evaluated_at timestamptz,actual_move numeric,actual_direction text,prediction_correct boolean,evaluation_ticks integer);
create index if not exists market_analysis_runs_symbol_created_idx on public.market_analysis_runs(symbol,created_at desc);
create table if not exists public.aiva_learning_state (symbol text primary key,confidence_threshold numeric not null default 0.65,evaluated_directional integer not null default 0,directional_accuracy numeric,updated_at timestamptz not null default now(),last_cycle_at timestamptz,last_decision text,last_error text);
create table if not exists public.aiva_demo_trades (id uuid primary key default gen_random_uuid(),symbol text not null,direction text not null,entry_price numeric not null,quantity numeric not null default 1,analysis_id uuid,exit_price numeric,pnl_points numeric,status text not null default 'OPEN',opened_at timestamptz not null default now(),closed_at timestamptz,close_reason text,context jsonb not null default '{}'::jsonb);
create index if not exists aiva_demo_trades_symbol_status_idx on public.aiva_demo_trades(symbol,status,opened_at desc);
create table if not exists public.aiva_backtest_runs (id uuid primary key default gen_random_uuid(),symbol text not null,method text not null,data_points integer,first_tick_at timestamptz,last_tick_at timestamptz,train_boundary_at timestamptz,overall jsonb,in_sample jsonb,out_of_sample jsonb,assumptions jsonb not null default '{}'::jsonb,warnings jsonb not null default '[]'::jsonb,trade_details jsonb not null default '[]'::jsonb,created_at timestamptz not null default now());
create index if not exists aiva_backtest_runs_symbol_created_idx on public.aiva_backtest_runs(symbol,created_at desc);
create table if not exists public.aiva_inverse_demo_state (strategy_key text not null,symbol text not null,last_processed_candle_at timestamptz,last_tick_at timestamptz,status text,updated_at timestamptz not null default now(),primary key(strategy_key,symbol));
create table if not exists public.aiva_inverse_demo_trades (id uuid primary key default gen_random_uuid(),strategy_key text not null,symbol text not null,source_signal_direction text,direction text not null,signal_candle_at timestamptz,entry_at timestamptz not null,entry_price numeric not null,stop_price numeric not null,target_price numeric not null,atr_points numeric,status text not null default 'OPEN',exit_at timestamptz,exit_price numeric,pnl_points numeric,close_reason text,closed_at timestamptz,context jsonb not null default '{}'::jsonb);
create index if not exists aiva_inverse_demo_trades_symbol_status_idx on public.aiva_inverse_demo_trades(strategy_key,symbol,status,entry_at desc);
create table if not exists public.paper_trades (id uuid primary key default gen_random_uuid(),symbol text,direction text,pnl numeric,status text,opened_at timestamptz,closed_at timestamptz,strategy_version text,context jsonb not null default '{}'::jsonb);
create table if not exists public.signals (id uuid primary key default gen_random_uuid(),symbol text,direction text,confidence numeric,risk_score numeric,strategy_version text,features jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.market_quotes enable row level security;
alter table public.market_quote_ticks enable row level security;
alter table public.aiva_historical_m1 enable row level security;
alter table public.aiva_historical_daily enable row level security;
alter table public.market_analysis_runs enable row level security;
alter table public.aiva_learning_state enable row level security;
alter table public.aiva_demo_trades enable row level security;
alter table public.aiva_backtest_runs enable row level security;
alter table public.aiva_inverse_demo_state enable row level security;
alter table public.aiva_inverse_demo_trades enable row level security;
alter table public.paper_trades enable row level security;
alter table public.signals enable row level security;